from google.cloud import translate_v3


def translate_dictionary_values(payload, config=None):
    config = config or {}
    client = translate_v3.TranslationServiceClient()
    parent = f"projects/{config['project_id']}/locations/{config.get('location', 'global')}"
    translated_dict = {}
    for key, value in payload["dictionary"].items():
        response = client.translate_text(request={
            "parent": parent,
            "contents": [value],
            "mime_type": "text/plain",
            "source_language_code": payload["source_language"],
            "target_language_code": payload["target_language"],
        })
        translated_dict[key] = response.translations[0].translated_text
    return {
        "translated_dictionary": translated_dict,
        "source_language": payload["source_language"],
        "target_language": payload["target_language"],
    }

from google.cloud import translate_v3

def get_translation_client():
    return translate_v3.TranslationServiceClient()

def get_parent_path(project_id, location='global'):
    return f"projects/{project_id}/locations/{location}"

from typing import Dict, List, Any

def create_text_request(contents: List[str], source_language: str, target_language: str, mime_type: str = "text/plain") -> Dict[str, Any]:
    return {
        "contents": contents,
        "mime_type": mime_type,
        "source_language_code": source_language,
        "target_language_code": target_language,
    }

def parse_translation_response(response) -> List[str]:
    return [translation.translated_text for translation in response.translations]

import google.generativeai as genai
import os

def summarize_translation_quality(payload, config=None):
    config = config or {}
    genai.configure(api_key=os.environ.get("GOOGLE_API_KEY"))
    model = genai.GenerativeModel('gemini-pro')
    prompt = f"Summarize the potential quality issues in this translation from {payload['source_language']} to {payload['target_language']}:\nSource: {payload['source_text']}\nTranslation: {payload['translated_text']}\nIssues: {payload.get('issues', '')}"
    response = model.generate_content(prompt)
    return {
        "summary": response.text,
        "source_language": payload["source_language"],
        "target_language": payload["target_language"],
    }

from google.cloud import language_v1

def check_unsafe_copy(payload, config=None):
    config = config or {}
    client = language_v1.LanguageServiceClient()
    document = language_v1.Document(content=payload["text"], type_=language_v1.Document.Type.PLAIN_TEXT)
    response = client.classify_text(request={
        "document": document
    })
    unsafe_categories = []
    for category in response.categories:
        # Example: Check for categories that might indicate unsafe content
        if "Adult" in category.name or "Violent" in category.name or "Hate speech" in category.name:
            unsafe_categories.append(category.name)
    return {
        "text": payload["text"],
        "is_unsafe": bool(unsafe_categories),
        "unsafe_categories": unsafe_categories,
    }

import google.generativeai as genai
